class ChatRoom {
  private participants = new Map<string, User>();
  send(from: string, to: string, message: string) {
    const recipient = this.participants.get(to);
    recipient?.receive({ from, message });
  }
  register(user: User) { this.participants.set(user.name, user); }
}
class User {
  constructor(public name: string, private room: ChatRoom) {}
  send(to: string, msg: string) { this.room.send(this.name, to, msg); }
  receive(m: any) { console.log(m); }
}

type Event = { type: string; payload: any };
class Coordinator {
  handle(event: Event) {
    switch (event.type) {
      case "OrderPlaced":
        PaymentService.process(event.payload);
        NotificationService.alert(event.payload);
        break;
      case "Refund":
        Accounting.update(event.payload);
        Auditor.log(event.payload);
        break;
      // many more cases appended over time
    }
  }
}

/* Version A */
class HubA {
  handle(msg:{type:string,payload:any}) {
    if (msg.type === "Pay") PaymentService.process(msg.payload);
    else if (msg.type === "Notify") NotificationService.send(msg.payload);
    // more conditionals accumulate here
  }
}

/* Version B */
class HubB {
  private handlers = new Map<string,(p:any)=>void>();
  register(type:string, h:(p:any)=>void){ this.handlers.set(type,h); }
  handle(msg:{type:string,payload:any}){ this.handlers.get(msg.type)?.(msg.payload); }
}
